import csv
import io
import re
from collections import Counter


def _tolerant_records(text):
    records = []
    row = []
    field = []
    quoted = False
    at_start = True
    i = 0

    while i < len(text):
        ch = text[i]

        if quoted:
            if ch == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                quoted = False
                i += 1
                continue
            field.append(ch)
            i += 1
            continue

        if ch == '"' and at_start:
            quoted = True
            at_start = False
            i += 1
            continue

        if ch == ",":
            row.append("".join(field))
            field = []
            at_start = True
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            field = []
            records.append(row)
            row = []
            at_start = True
            if ch == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        at_start = False
        i += 1

    if field or row or (text and text[-1] == ","):
        row.append("".join(field))
        records.append(row)

    return records


def _read_records(text):
    try:
        try:
            csv.field_size_limit(2147483647)
        except (OverflowError, ValueError):
            pass
        return [list(row) for row in csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"')]
    except csv.Error:
        return _tolerant_records(text)


def _is_blank(row):
    return not row or all(value == "" for value in row)


def _textual_score(row):
    nonempty = [value.strip() for value in row if value.strip()]
    if not nonempty:
        return 0.0
    alpha = sum(1 for value in nonempty if re.search(r"[A-Za-z]", value))
    numeric = sum(1 for value in nonempty if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", value))
    return alpha * 2.0 - numeric + len(nonempty) * 0.1


def _header_candidate(records, start, width):
    block = records[start:start + 3]
    if len(block) != 3:
        return None

    lengths = [len(row) for row in block]
    if sum(lengths) == width:
        columns = []
        for row in block:
            columns.extend(row)
        mode_score = 20.0
    elif all(length == width for length in lengths):
        columns = []
        for column_index in range(width):
            parts = [row[column_index].strip() for row in block if row[column_index].strip()]
            columns.append(" ".join(parts))
        mode_score = 10.0
    else:
        return None

    if len(columns) != width:
        return None

    score = mode_score + sum(_textual_score(row) for row in block)
    if start + 3 < len(records):
        next_width = len(records[start + 3])
        if next_width == width:
            score += 5.0
        elif 2 <= next_width <= width + 5:
            score += 1.0
    return score, columns


def _find_header(records, width):
    best = None
    for index in range(max(0, len(records) - 2)):
        candidate = _header_candidate(records, index, width)
        if candidate is None:
            continue
        score, columns = candidate
        ranked = (score - index * 0.001, -index, columns, index)
        if best is None or ranked[:2] > best[:2]:
            best = ranked

    if best is not None:
        return best[3], best[2]

    columns = []
    for row in records[:3]:
        columns.extend(row)
    columns = columns[:width]
    while len(columns) < width:
        columns.append("column_" + str(len(columns) + 1))
    return 0, columns


def _is_trailing_metadata(row, width):
    if _is_blank(row):
        return True
    if len(row) >= width:
        return False
    joined = ",".join(row).strip()
    if not joined:
        return True
    return bool(re.match(r"^[A-Za-z][A-Za-z0-9 _./()\-]{0,100}:\s*\S", joined))


def _repair_semicolons(row, width):
    if len(row) >= width:
        return row

    deficit = width - len(row)
    options = []

    def visit(index, remaining, built):
        if index == len(row):
            if remaining == 0:
                options.append(built)
            return

        value = row[index]
        visit(index + 1, remaining, built + [value])

        if remaining > 0 and ";" in value:
            parts = value.split(";")
            added = len(parts) - 1
            if added <= remaining:
                visit(index + 1, remaining - added, built + parts)

    visit(0, deficit, [])
    if not options:
        return row

    def option_score(candidate):
        score = 0
        for index, value in enumerate(candidate):
            if value == "":
                score += 1
            if index < len(row) and ";" in row[index]:
                score -= 1
        return score

    return min(options, key=option_score)


def _shape(value):
    stripped = value.strip()
    if stripped == "":
        return "empty"
    if re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", stripped) or stripped.lower().startswith("www."):
        return "url"
    if re.fullmatch(r"\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}", stripped):
        return "date"
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?", stripped):
        return "time"
    if re.fullmatch(r"[$€£¥]\s*[-+]?\d[\d,]*(?:\.\d+)?", stripped):
        return "currency"
    if re.fullmatch(r"[-+]?\d+", stripped):
        return "integer"
    if re.fullmatch(r"[-+]?(?:\d+\.\d*|\d*\.\d+)", stripped):
        return "decimal"
    if re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", stripped):
        return "email"
    return "text"


def _build_profiles(rows, width):
    profiles = []
    for column in range(width):
        values = [row[column] for row in rows if len(row) == width]
        shapes = Counter(_shape(value) for value in values)
        nonempty_lengths = [len(value) for value in values if value != ""]
        average = (
            float(sum(nonempty_lengths)) / len(nonempty_lengths)
            if nonempty_lengths else 0.0
        )
        dominant = shapes.most_common(1)[0][0] if shapes else None
        dominance = (
            float(shapes[dominant]) / len(values)
            if dominant is not None and values else 0.0
        )
        profiles.append((dominant, dominance, average, len(values)))
    return profiles


def _row_score(row, profiles):
    score = 0.0
    for index, value in enumerate(row):
        dominant, dominance, average, count = profiles[index]
        if not count:
            continue

        shape = _shape(value)
        if dominance >= 0.65 and shape != dominant:
            if shape == "empty" or dominant == "empty":
                score += 8.0
            elif {shape, dominant} <= {"integer", "decimal"}:
                score += 1.0
            else:
                score += 12.0

        if shape == "text" and average > 0:
            score += min(5.0, abs(len(value) - average) / (average + 5.0))
    return score


def _normalize_row(row, width, profiles):
    row = _repair_semicolons(list(row), width)

    if len(row) == width:
        return row

    if len(row) > width:
        surplus = len(row) - width
        candidates = []
        for position in range(width):
            end = position + surplus + 1
            if end <= len(row):
                candidate = row[:position] + [",".join(row[position:end])] + row[end:]
                if len(candidate) == width:
                    candidates.append(candidate)
        if candidates:
            return min(candidates, key=lambda item: _row_score(item, profiles))
        return row[:width - 1] + [",".join(row[width - 1:])]

    deficit = width - len(row)
    candidates = []
    for position in range(len(row) + 1):
        candidate = row[:position] + [""] * deficit + row[position:]
        candidates.append(candidate)
    if candidates:
        return min(candidates, key=lambda item: _row_score(item, profiles))
    return [""] * width


def parse_csv(raw_csv: str):
    width = 9
    records = _read_records(raw_csv)

    if records and records[0]:
        records[0][0] = records[0][0].lstrip("\ufeff")

    records = [row for row in records if not _is_blank(row)]
    header_index, columns = _find_header(records, width)

    data = records[header_index + 3:]

    while data and _is_trailing_metadata(data[-1], width):
        data.pop()

    prelim = [_repair_semicolons(row, width) for row in data]
    exact_rows = [row for row in prelim if len(row) == width]
    profiles = _build_profiles(exact_rows, width)
    rows = [_normalize_row(row, width, profiles) for row in prelim]

    return {"columns": [str(value) for value in columns], "rows": rows}
